            product = self._catalog.get(item.sku)
            lines.append({"sku": item.sku,
                          "name": product.name if product is not None else None,
                          "quantity": item.quantity})
        return Response(200, {
            "order_id": order.order_id,
            "customer_name": customer.name if customer is not None else None,
            "lines": lines,
        })

    def handle_low_stock(self, threshold: Any) -> Response:
        try:
            limit = require_non_negative_int(threshold, "threshold")
        except InvalidRequest as exc:
            return bad_request(exc)
        low = []
        for product in self._catalog.list_all():
            if not product.active:
                continue
            on_hand = self._stock.get(product.sku)
            if on_hand < limit:
                low.append((on_hand, product))
        low.sort(key=lambda entry: (entry[0], entry[1].sku))
        return Response(200, {"products": [
            {"sku": product.sku, "name": product.name, "on_hand": on_hand}
            for on_hand, product in low
        ]})

    def handle_restock(self, request: dict[str, Any]) -> Response:
        try:
            sku = require_str(request, "sku")
            quantity = require_positive_int(request.get("quantity"), "quantity")
        except InvalidRequest as exc:
            return bad_request(exc)
        if self._catalog.get(sku) is None:
            return not_found("product")
        on_hand = self._stock.get(sku) + quantity
        self._stock.set(sku, on_hand)
        return Response(200, {"sku": sku, "on_hand": on_hand})

def test_low_stock_lists_active_products_below_threshold_sorted_by_on_hand_then_sku(shop):
    # shop: BOOK on_hand 50, LAMP on_hand 5, PEN on_hand 100
    shop.catalog.handle_add_product({"sku": "CUP", "name": "Cup", "unit_price_cents": 800, "on_hand": 5})
    shop.catalog.handle_add_product({"sku": "MUG", "name": "Mug", "unit_price_cents": 900, "on_hand": 2})
    response = shop.fulfilment.handle_low_stock(10)
    assert response.status == 200
    assert response.body == {"products": [
        {"sku": "MUG", "name": "Mug", "on_hand": 2},
        {"sku": "CUP", "name": "Cup", "on_hand": 5},
        {"sku": "LAMP", "name": "Lamp", "on_hand": 5},
    ]}


